const byLoc = { ar, fr, en, de }

// Ensure `common.tipLabel` key exists
const tipLabel = { ar: 'نصيحة', fr: 'Astuce', en: 'Tip', de: 'Tipp' }

for (const loc of ['ar', 'fr', 'en', 'de']) {
  const p = path.join(__dirname, '..', 'messages', `${loc}.json`)
  const j = JSON.parse(fs.readFileSync(p, 'utf8'))
  j.static = j.static || {}
  j.static.banking = byLoc[loc]
  j.common = j.common || {}
  j.common.tipLabel = tipLabel[loc]
  fs.writeFileSync(p, JSON.stringify(j, null, 2) + '\n', 'utf8')
  console.log(`✓ ${loc}.json`)
}
